fn LeftShift(x1: List[Int], x2: List[Int]) -> List[Int]
  requires (len(x1) == len(x2))
  requires forall i in 0..len(x2): (x2[i] >= 0)
  ensures (len(result) == len(x1))
  ensures forall i in 0..len(result): (result[i] == (x1[i] * Power(2, x2[i])))
  ensures forall i in 0..len(result): ((not (x2[i] == 0)) or (result[i] == x1[i]))
  ensures forall i in 0..len(result): ((not (x1[i] == 0)) or (result[i] == 0))
  ensures forall i in 0..len(result): ((not ((x1[i] > 0) and (x2[i] > 0))) or (result[i] > x1[i]))
  ensures forall i in 0..len(result): ((not ((x1[i] < 0) and (x2[i] > 0))) or (result[i] < x1[i]))
  effects pure
  example (LeftShift([1, 2, 3], [0, 1, 2]) == [1, 4, 12])
  example (LeftShift([], []) == [])
{
  match x1 {
    [] => []
    [h1, ..t1] => match x2 {
      [] => []
      [h2, ..t2] => [h1 * Power(2, h2)] ++ LeftShift(t1, t2)
    }
  }
}

fn LogicalAnd(x1: List[Bool], x2: List[Bool]) -> List[Bool]
  requires (len(x1) == len(x2))
  ensures (len(result) == len(x1))
  ensures forall i in 0..len(result): (result[i] == (x1[i] and x2[i]))
  effects pure
  example LogicalAnd([], []) == []
  example LogicalAnd([true], [false]) == [false]
  example LogicalAnd([true, false], [true, true]) == [true, false]
{
  match x1 {
    [] => []
    [h1, ..t1] => match x2 {
      [] => []
      [h2, ..t2] => [h1 and h2] ++ LogicalAnd(t1, t2)
    }
  }
}

